namespace ImageGuide;

public sealed partial class GuideForm
{
    async Task Build()
    {
        if(busy||result==null||editions.SelectedItem is not Edition edition)return;
        CheckCurrent();if(result==null)return;
        using(var confirm=Dialog("Create a separate ISO — review",new Size(760,480))){var panel=Stack();panel.Padding=new Padding(16);panel.Controls.Add(TextLabel("Your original ISO stays untouched.","All output is confined to a new run folder."));panel.Controls.Add(TextLabel("This creates a new ISO with all existing editions. It does not apply your future goals or slim Windows. Boot and Windows installation still need testing.","Media creation is separate from unsupported Windows servicing."));panel.Controls.Add(TextLabel(preferEdition.Checked?$"Setup preference: {edition.Name}, Retail channel. No Windows license or activation is provided. Existing setup configuration will block this option.":"Setup preference: unchanged. All original setup settings are preserved.","The Retail preference is an explicit choice, not inferred licensing."));panel.Controls.Add(TextLabel("Pause and Cancel wait for active native work to finish. Cancel keeps leftovers by default; you may choose guarded cleanup afterward. Undo changes choices before building; it never rewrites an already created ISO.","No forced process termination, source deletion or image servicing occurs."));var actions=Flow();var no=Button("Go back");var yes=Button("Create separate ISO");Help(no,"Return without creating files or changing your selections.");Help(yes,"Create a separate ISO using exactly the changes shown above. Your original stays read-only.");no.DialogResult=DialogResult.Cancel;yes.DialogResult=DialogResult.OK;actions.Controls.Add(no);actions.Controls.Add(yes);panel.Controls.Add(actions);confirm.Controls.Add(panel);confirm.CancelButton=no;confirm.AcceptButton=no;if(confirm.ShowDialog(this)!=DialogResult.OK)return;}
        string? folder=NewFolder("Choose a parent folder for a NEW media build (allow three times the ISO size plus 1 GB)");if(folder==null)return;
        var observed=result;var choices=new MediaBuildChoices(edition.Index,preferEdition.Checked);using var active=new JobControl();job=active;busy=true;activity=Activity.Building;critical=false;pause.Text="Pause";RefreshActions();bool canceled=false;
        try{
            BeginTelemetry();var progress=new Progress<JobProgress>(p=>{if(job!=active)return;ObserveTelemetry(p);critical=p.Phase.StartsWith("Final",StringComparison.Ordinal)||p.Phase=="Verifying source identity";SetStatus(p.Phase+": "+p.Message,p.Phase+(p.IsPaused?" — paused safely":p.CancellationPending?" — cancellation waiting for safe completion":""));RefreshActions();});
            var built=await Engine.BuildIso(observed,choices,folder,active,progress);SetStatus("Created a separate ISO: "+built.IsoPath+"\nOriginal SHA-256: "+built.SourceSha256+"\nNew ISO SHA-256: "+built.OutputSha256+"\nAll editions preserved. Future goals were not applied. Boot, installation and setup preference behavior have NOT been tested.","Separate ISO created. Open Full details for its location and remaining checks.");
        }catch(OperationCanceledException){canceled=true;SetStatus("Build canceled after safe native completion and original-file verification. No completed ISO was published. Leftovers are kept unless you choose cleanup.");}
        catch(Exception ex){SetStatus("ISO build failed: "+ex.Message+"\nKeep the run folder and review its evidence. No completed ISO is approved for use.");}
        finally{EndTelemetry();job=null;busy=false;activity=Activity.Idle;critical=false;CheckCurrent();ShowStep();}
        if(canceled)OfferBuildCleanup(folder,active.RunId);
    }
    void OfferBuildCleanup(string folder,Guid id)
    {
        if(!Directory.Exists(folder))return;var preview=Engine.PreviewBuildCleanup(folder,id);
        using var dialog=BuildCleanupDialog(folder,id,preview);dialog.ShowDialog(this);
    }
