    {
        var dialog=Dialog("Canceled build — keep leftover files?",new Size(820,560));var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=1,RowCount=3};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));var intro=TextLabel($"Keep files is the default. {preview.Files.Count:N0} unchanged generated files ({preview.TotalBytes:N0} bytes) are eligible. Folders, changed files and unrelated entries are retained.","Source ISO and completed output are never cleanup targets.");intro.MaximumSize=new Size(760,0);layout.SizeChanged+=(_,_)=>intro.MaximumSize=new Size(Math.Max(100,layout.ClientSize.Width-layout.Padding.Horizontal),0);layout.Controls.Add(intro,0,0);var details=ReadBox(350);Help(details,"Exact eligible generated-file list and cleanup warnings. Read-only, selectable and scrollable; source ISO is excluded.");details.AccessibleName="Build cleanup files and warnings";details.Text=folder+Environment.NewLine+string.Join(Environment.NewLine,preview.Files.Select(x=>x.RelativePath+" ("+x.Bytes+" bytes)").Concat(preview.Warnings));layout.Controls.Add(details,0,1);var actions=Flow();var keep=Button("Keep files (recommended)");Help(keep,"Keep all leftovers. This is the default choice and closes the dialog without deleting files.");keep.DialogResult=DialogResult.Cancel;var remove=Button("Delete eligible files from this run");Help(remove,"Delete only unchanged generated files owned by this safely canceled build. Folders and unknown files remain. Disabled if ownership is unconfirmed.");remove.Enabled=preview.CanDelete;actions.Controls.Add(keep);actions.Controls.Add(remove);layout.Controls.Add(actions,0,2);remove.Click+=(_,_)=>{var outcome=Engine.CleanupBuild(folder,id);ShowDetails("Build cleanup result",$"Removed: {outcome.Removed.Count}. Retained: {outcome.Retained.Count}. Errors: {outcome.Errors.Count}. Folders retained.\n"+string.Join(Environment.NewLine,outcome.Retained.Concat(outcome.Errors)),dialog);dialog.Close();};dialog.Controls.Add(layout);dialog.CancelButton=keep;dialog.AcceptButton=keep;return dialog;
    }
